import json, sys

path = sys.argv[1]
maxlen = 800

def get_text(content):
    out = []
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        for c in content:
            if not isinstance(c, dict):
                continue
            t = c.get('type')
            if t == 'text':
                out.append(c.get('text',''))
            elif t == 'tool_use':
                inp = c.get('input', {})
                inp_s = json.dumps(inp)
                if len(inp_s) > maxlen:
                    inp_s = inp_s[:maxlen] + '...[TRUNC]'
                out.append(f"[TOOL_USE {c.get('name')}] {inp_s}")
            elif t == 'tool_result':
                cont = c.get('content')
                if isinstance(cont, list):
                    s = ' '.join(x.get('text','') for x in cont if isinstance(x, dict))
                else:
                    s = str(cont)
                if len(s) > maxlen:
                    s = s[:maxlen] + f"...[TRUNC total_len={len(s)}]"
                out.append(f"[TOOL_RESULT] {s}")
    return '\n'.join(out)

with open(path) as f:
    for i, line in enumerate(f):
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except Exception as e:
            print(f"--- line {i}: PARSE ERROR {e}")
            continue
        ts = obj.get('timestamp', '')
        typ = obj.get('type', obj.get('role',''))
        msg = obj.get('message', obj)
        role = msg.get('role', typ) if isinstance(msg, dict) else typ
        content = msg.get('content') if isinstance(msg, dict) else None
        text = get_text(content) if content is not None else ''
        if not text:
            continue
        print(f"--- [{i}] {ts} role={role}")
        print(text[:maxlen*3])
        print()

import subprocess, json, sys
from datetime import datetime

files = sys.argv[1:]

def get(f):
    r = subprocess.run(["git","show",f"origin/conversation-logs:{f}"], cwd="/home/user/Claudinite", capture_output=True, text=True)
    return r.stdout

def parse(t):
    return datetime.fromisoformat(t.replace("Z","+00:00"))

def brief(obj):
    msg = obj.get("message", {})
    role = msg.get("role") if isinstance(msg, dict) else obj.get("type")
    content_list = msg.get("content") if isinstance(msg, dict) else None
    parts = []
    if isinstance(content_list, list):
        for c in content_list:
            if isinstance(c, dict):
                t = c.get("type")
                if t == "tool_use":
                    inp = c.get("input", {})
                    cmd = inp.get("command") if isinstance(inp, dict) else None
                    parts.append(f"tool_use:{c.get('name')}" + (f" cmd={str(cmd)[:80]}" if cmd else ""))
                elif t == "tool_result":
                    cc = c.get("content")
                    s = cc if isinstance(cc, str) else json.dumps(cc)[:100]
                    parts.append(f"tool_result[err={c.get('is_error')}]: {str(s)[:100]}")
                elif t == "text":
                    parts.append(f"text: {c.get('text','')[:150]}")
    elif isinstance(content_list, str):
        parts.append(content_list[:150])
    return f"[{role}] " + " | ".join(parts)

for f in files:
    content = get(f)
    lines = content.splitlines()
    entries = []
    for i, line in enumerate(lines):
        if not line.strip(): continue
        try:
            obj = json.loads(line)
        except Exception:
            continue
        ts = obj.get("timestamp")
        if ts:
            entries.append((i, parse(ts), obj))
    if len(entries) < 2:
        print(f"FILE {f}: too few timestamped entries")
        continue
    gaps = []
    for j in range(1, len(entries)):
        gap = (entries[j][1] - entries[j-1][1]).total_seconds()
        gaps.append((gap, j))
    gaps.sort(reverse=True)
    print(f"=== FILE {f} === total entries={len(entries)}")
    for gap, j in gaps[:5]:
        i_before, t_before, obj_before = entries[j-1]
        i_after, t_after, obj_after = entries[j]
        print(f"  GAP {gap:.1f}s between line {i_before} ({t_before}) and line {i_after} ({t_after})")
        print(f"    BEFORE: {brief(obj_before)[:200]}")
        print(f"    AFTER : {brief(obj_after)[:200]}")
    print()

